import {warsawClassDay,scheduleClasses} from './crm-schedule.js';
import {buildAnalytics,shiftDay} from './crm-analytics.js';
import {trialTypes,trialsForDay,trialLeadCount} from './crm-trials.js';
import {warsawToIso} from './private-lessons.js';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const statuses=['New','Contacted','Trial Booked','Trial Attended','Converted','Closed'];
let analyticsRange=null,discounts=[],discountStatus='all';
let data={leads:[],classes:[],bookings:[],students:[],memberships:[],history:[]},authorised=false,busy=false,filter={};
const rpc=async(action,payload={})=>{const response=await fetch('/api/crm',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,payload})});const body=await response.json();if(!response.ok){if(response.status===401){authorised=false;data={leads:[],classes:[],bookings:[],students:[],memberships:[],history:[]};$('#workspace').hidden=true;$('#auth').hidden=false;$('#staff-nav').hidden=true;$('#detail').close();}throw Error(body.message||'Unable to complete request');}return body;};
const login=(email,password)=>rpc('login',{email,password}),logout=()=>rpc('logout');
const day=warsawClassDay;
const today=()=>day(new Date()), date=value=>value?new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Warsaw',dateStyle:'medium',timeStyle:'short'}).format(new Date(value)):'—';
const local=value=>{const parts=Object.fromEntries(new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Warsaw',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(value)).map(p=>[p.type,p.value]));return `${parts.year}-${parts.month}-${parts.day}T${parts.hour}:${parts.minute}`;};
const field=(name,label,value='',type='text',extra='')=>`<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const select=(name,label,options,value='')=>`<label>${esc(label)}<select name="${name}">${options.map(option=>{const [v,label]=Array.isArray(option)?option:[option,option];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(label)}</option>`;}).join('')}</select></label>`;
const button=(label,action,id='',extra='')=>`<button type="button" data-action="${action}" data-id="${id}" ${extra}>${label}</button>`;
const active=c=>data.bookings.filter(b=>b.class_id===c.id&&b.status==='Booked');
const person=b=>data.students.find(s=>s.id===b.student_id)||data.leads.find(l=>l.id===b.lead_id)||{name:'Unknown'};
const message=(text,error=false)=>{$('#status').textContent=text;$('#status').className=error?'error':'';};
function modal(title,html){$('#detail-title').textContent=title;$('#detail-body').innerHTML=html;if(!$('#detail').open)$('#detail').showModal();}
function history(lead,student){const items=data.history.filter(h=>(lead&&h.lead_id===lead)||(student&&(h.student_id===student||data.leads.some(l=>l.id===h.lead_id&&l.student_id===student))));return `<h3 class="section-title">History</h3><ul class="history">${items.map(h=>`<li><small>${esc(date(h.created_at))}</small><strong>${esc(h.event)}</strong><div>${esc(h.detail)}</div></li>`).join('')||'<li>No history yet.</li>'}</ul>`;}
async function reload(){data=await rpc('load');if(location.hash==='#discounts')discounts=await rpc('discount_list');render();}
async function mutate(action,payload){if(busy)return false;busy=true;document.querySelectorAll('dialog button').forEach(b=>b.disabled=true);try{const result=await rpc(action,payload);await reload();message('Saved.');return result;}catch(error){message(error.message,true);let note=$('#detail .form-error');if(!note){note=document.createElement('p');note.className='form-error error';note.setAttribute('role','alert');$('#detail-body').prepend(note);}note.textContent=error.message;return false;}finally{busy=false;document.querySelectorAll('dialog button').forEach(b=>b.disabled=false);}}
function classRows(classes){return classes.map(c=>`<article class="card row"><div><strong>${esc(c.group_name)}</strong> <span class="pill">${esc(c.class_type)}</span><p>${esc(date(c.starts_at))} – ${esc(new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Warsaw',timeStyle:'short'}).format(new Date(c.ends_at)))}</p><small>${esc(c.instructor)} · ${esc(c.room)}</small></div><div class="actions"><span>${active(c).length} / ${c.capacity} spots</span>${button('Roster','roster',c.id)}${button('Edit','class',c.id)}</div></article>`).join('')||'<div class="card empty">No classes here yet. Add a class in Schedule.</div>';}
function render(){if(!authorised)return;const route=location.hash.slice(1)||'today';document.body.dataset.crmPage=route;document.querySelectorAll('#staff-nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+route));$('#page-title').textContent=({today:'Today',leads:'Leads & contact requests',schedule:'Classes & bookings',students:'Students & memberships',analytics:'Analytics',discounts:'Class discounts'})[route]||'Today';
 if(route==='discounts')renderDiscounts();else if(route==='analytics')renderAnalytics();else if(route==='leads')renderLeads();else if(route==='schedule')renderSchedule();else if(route==='students')renderStudents();else renderToday();}
function renderToday(){const classes=data.classes.filter(c=>!c.cancelled&&day(c.starts_at)===today());const trialToday=trialsForDay(data,today(),day);const categories=[...trialTypes,...(trialsForDay(data,today(),day,'other').length?[['other','Other classes']]:[])];const overdue=data.leads.filter(l=>l.follow_up&&l.follow_up<today()&&!['Closed','Converted'].includes(l.status));$('#workspace').innerHTML=`<p>${esc(new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Warsaw',dateStyle:'full'}).format(new Date()))} · Warsaw time</p><div class="stats">${[['New inquiries',data.leads.filter(l=>l.status==='New').length,'new'],['Trials today',trialLeadCount(trialToday),'trials'],['Overdue follow-ups',overdue.length,'overdue']].map(([label,count,id])=>`<button class="metric" data-action="metric" data-id="${id}"><strong>${count}</strong>${label} →</button>`).join('')}</div><h2>Trials today by class</h2><div class="stats trial-type-stats">${categories.map(([type,label])=>`<button class="metric" data-action="metric" data-id="trials-${type}"><strong>${trialLeadCount(trialsForDay(data,today(),day,type))}</strong>${label} →</button>`).join('')}</div><h2>Today’s classes</h2><div class="list">${classRows(classes)}</div>`;}
function filteredLeads(){let list=data.leads;const q=(filter.search||'').toLowerCase();if(q)list=list.filter(l=>[l.name,l.email,l.phone,l.preference].some(v=>(v||'').toLowerCase().includes(q)));if(filter.status)list=list.filter(l=>l.status===filter.status);if(filter.source)list=list.filter(l=>l.source===filter.source);if(filter.follow==='overdue')list=list.filter(l=>l.follow_up&&l.follow_up<today()&&!['Converted','Closed'].includes(l.status));if(filter.follow==='today')list=list.filter(l=>l.follow_up===today());if(filter.follow==='dated')list=list.filter(l=>l.follow_up===filter.date);if(filter.trials){const ids=new Set(trialsForDay(data,today(),day,filter.trialType||'').map(b=>b.lead_id));list=list.filter(l=>ids.has(l.id));}return list;}
function renderLeads(){const rows=filteredLeads();$('#workspace').innerHTML=`<form id="lead-filters" class="toolbar">${field('search','Search name, email, phone',filter.search||'','search')}${select('status','Status',[['','All statuses'],...statuses],filter.status||'')}${select('source','Source',[['','All sources'],...[...new Set(data.leads.map(l=>l.source))]],filter.source||'')}${select('follow','Follow-up',[['','Any date'],['overdue','Overdue'],['today','Today'],['dated','On date']],filter.follow||'')}${field('date','Follow-up date',filter.date||'','date')}<button>Filter</button>${button('Clear','clear')}${button('Add lead','lead','','class="primary"')}</form>${filter.trials?`<p class="notice">${esc([...trialTypes,['other','Other classes']].find(([type])=>type===filter.trialType)?.[1]||'All classes')} · trial lessons scheduled for today.</p>`:''}<p class="count">${rows.length} leads</p><div class="list">${rows.map(l=>`<article class="card row"><div><strong>${esc(l.name)}</strong> <span class="pill">${esc(l.status)}</span><p>${esc(l.email||l.phone)} · ${esc(l.source)}</p><small>Follow-up: ${esc(l.follow_up||'Not set')}</small></div>${button('Open lead','lead',l.id)}</article>`).join('')||'<div class="card empty">No matching leads.</div>'}</div>`;}
function renderSchedule(){const from=filter.classDate||'',all=scheduleClasses(data.classes),rows=scheduleClasses(data.classes,from);const empty=all.length?('No classes match '+from+'. Choose another date or use All dates.'):'No classes have been added to the CRM schedule yet. Use Add class to create the first one. Website timetable entries are not automatically CRM classes.';$('#workspace').innerHTML=`<form id="schedule-filter" class="toolbar">${field('date','Class date',from,'date')}<button type="submit">Filter</button>${button('All dates','schedule-clear')}${button('Add class','class','','class="primary"')}</form><p class="count" role="status">${rows.length} of ${all.length} classes · ${from?esc(from)+' · Warsaw time':'All dates'}</p><div class="list">${rows.length?classRows(rows):'<div class="card empty">'+esc(empty)+'</div>'}</div>`;}
function leadDialog(id){const l=data.leads.find(l=>l.id===id)||{};const bookings=data.bookings.filter(b=>b.lead_id===id);modal(l.name||'Add lead',`<form data-form="lead"><input type="hidden" name="id" value="${esc(l.id||'')}"><div class="two">${field('name','Full name',l.name||'','text','required maxlength="120"')}${field('email','Email',l.email||'','email')}${field('phone','Phone',l.phone||'','tel')}${select('contact_method','Preferred contact',['Email','Phone','WhatsApp'],l.contact_method||'Email')}${field('source','Source',l.source||'Manual')}${select('status','Status',statuses.map(x=>[x,x]),l.status||'New')}${field('follow_up','Next follow-up',l.follow_up||'','date')}${field('preference','Preferred class / availability',l.preference||'')}</div><label>Add a dated note<textarea name="note" maxlength="5000"></textarea></label><p class="count">Book trials, mark attendance and convert using the actions below. These statuses are updated automatically.</p><button class="primary">Save lead</button></form>${id?`<div class="actions section-title">${button('Book / reschedule trial','book',id)}${button(l.student_id?'Open student':'Convert to student',l.student_id?'student':'convert',l.student_id||id)}</div><h3>Trial bookings</h3>${bookings.map(b=>{const c=data.classes.find(c=>c.id===b.class_id);return `<div class="card"><strong>${esc(c?.group_name)} · ${esc(date(c?.starts_at))}</strong><p>${esc(b.status)} · ${esc(b.attendance)}</p>${b.status==='Booked'?`<div class="actions">${button('Roster / attendance','roster',b.class_id)}${button('Cancel booking','cancel',b.id)}</div>`:''}</div>`;}).join('')||'<p>No trial booked.</p>'}${history(id,l.student_id)}`:''}`);}
function bookDialog(leadId='',studentId=''){const l=data.leads.find(l=>l.id===leadId),student=data.students.find(s=>s.id===studentId);const upcoming=data.classes.filter(c=>!c.cancelled&&new Date(c.starts_at)>new Date());const existing=data.bookings.filter(b=>b.lead_id===leadId&&b.status==='Booked');modal('Book '+(l?.name||student?.name||''),`<form data-form="book"><input type="hidden" name="lead_id" value="${esc(leadId)}"><input type="hidden" name="student_id" value="${esc(studentId)}">${select('class_id','Class',[['','Choose a class'],...upcoming.map(c=>[c.id,`${c.group_name} · ${date(c.starts_at)} · ${active(c).length}/${c.capacity} spots${active(c).length>=c.capacity?' · FULL':''}`])])}${leadId?select('replace_booking','Reschedule existing trial (optional)',[['','Add a new booking'],...existing.map(b=>{const c=data.classes.find(c=>c.id===b.class_id);return [b.id,`${c?.group_name} · ${date(c?.starts_at)} · ${b.attendance}`];})]):''}<p class="notice">The booking is confirmed only when saved. Full classes and conflicting bookings are rejected automatically.</p><button class="primary">Confirm booking</button></form>`);}
function classDialog(id){const c=data.classes.find(c=>c.id===id)||{};modal(c.id?'Edit class':'Create class',`<form data-form="class"><input type="hidden" name="id" value="${esc(c.id||'')}"><div class="two">${field('group_name','Group name',c.group_name||'','text','required placeholder="e.g. Newborn or Toddler"')}${select('class_type','Class type',['Single partner group','Couple group','Ladies’ Solo','Private class'],c.class_type||'Single partner group')}${field('instructor','Instructor',c.instructor||'','text','required')}${field('room','Studio / room',c.room||'','text','required')}${field('starts_at','Starts · Warsaw',c.starts_at?local(c.starts_at):'','datetime-local','required')}${field('ends_at','Ends · Warsaw',c.ends_at?local(c.ends_at):'','datetime-local','required')}${field('capacity','Capacity (people)',c.capacity||16,'number','required min="1" max="200"')}</div><button class="primary">Save class</button></form>`);}
function roster(id){const c=data.classes.find(c=>c.id===id);if(!c)return;modal(`${c.group_name} · Roster`, `<p>${esc(date(c.starts_at))} · ${esc(c.room)} · ${esc(c.instructor)}</p><p>${active(c).length} / ${c.capacity} people booked</p><div class="table-scroll"><table class="roster"><thead><tr><th>Student / lead</th><th>Contact</th><th>Attendance</th><th>Actions</th></tr></thead><tbody>${active(c).map(b=>{const p=person(b);return `<tr><td>${esc(p.name)}${b.lead_id?'<small>Trial / lead</small>':''}</td><td>${esc(p.email||p.phone||'')}</td><td><select aria-label="Attendance for ${esc(p.name)}" data-attendance="${b.id}">${['Pending','Present','Absent','No-show'].map(v=>`<option ${b.attendance===v?'selected':''}>${v}</option>`).join('')}</select></td><td>${button('Cancel','cancel',b.id)}</td></tr>`;}).join('')||'<tr><td colspan="4">No bookings yet.</td></tr>'}</tbody></table></div><p class="count">Present trial attendees update to Trial Attended automatically. A no-show is recorded in history; use the lead record to reschedule.</p>`);}
function renderStudents(){const q=(filter.studentSearch||'').toLowerCase();const rows=data.students.filter(s=>[s.name,s.email,s.phone].some(v=>(v||'').toLowerCase().includes(q)));$('#workspace').innerHTML=`<form id="student-filter" class="toolbar">${field('search','Search students',filter.studentSearch||'','search')}<button>Search</button></form><div class="list">${rows.map(s=>{const current=data.memberships.find(m=>m.student_id===s.id&&m.starts_on<=today()&&m.expires_on>=today());return `<article class="card row"><div><strong>${esc(s.name)}</strong><p>${esc(s.email||s.phone)} · ${esc(s.group_name||'No group assigned')}</p><small>${current?`${esc(current.plan)} · ${current.remaining_sessions}/${current.total_sessions} sessions · expires ${esc(current.expires_on)}`:'No current membership'}</small></div>${button('Open student','student',s.id)}</article>`;}).join('')||'<div class="card empty">Convert a lead to create a student.</div>'}</div>`;}
function studentDialog(id){const s=data.students.find(s=>s.id===id);if(!s)return;const memberships=data.memberships.filter(m=>m.student_id===id);const bookings=data.bookings.filter(b=>b.student_id===id);modal(s.name,`<p>${esc(s.email||'')} · ${esc(s.phone||'')}<br>Group: ${esc(s.group_name||'Not assigned')}</p><div class="actions">${button('Add membership','membership',id)}${button('Book class','student-book',id)}</div><h3 class="section-title">Memberships</h3>${memberships.map(m=>`<div class="card"><strong>${esc(m.plan)}</strong><p>${esc(m.starts_on)} → ${esc(m.expires_on)} · ${m.remaining_sessions} / ${m.total_sessions} sessions left</p></div>`).join('')||'<p>No membership recorded.</p>'}<h3 class="section-title">Attendance & classes</h3><ul>${bookings.map(b=>{const c=data.classes.find(c=>c.id===b.class_id);return `<li>${esc(c?.group_name)} · ${esc(date(c?.starts_at))} · ${esc(b.attendance)} · ${esc(b.status)}</li>`;}).join('')||'<li>No attendance history.</li>'}</ul>${history(null,id)}`);}
function membershipDialog(id){const s=data.students.find(s=>s.id===id);modal('Record membership',`<p>${esc(s.name)} · Payment processing is outside this CRM.</p><form data-form="membership"><input type="hidden" name="student_id" value="${id}"><div class="two">${field('plan','Plan name','','text','required placeholder="First Embrace · 4 classes"')}${field('group_name','Group',s.group_name)}${field('starts_on','Start date',today(),'date','required')}${field('expires_on','Expiration date','','date','required')}${field('total_sessions','Total sessions',4,'number','required min="1" max="1000"')}${field('remaining_sessions','Remaining sessions',4,'number','required min="0" max="1000"')}</div><button class="primary">Record purchase</button></form>`);}
$('#login').onsubmit=async event=>{event.preventDefault();const b=event.submitter||event.target.querySelector('button');b.disabled=true;try{const d=new FormData(event.target);const access=await login(d.get('email'),d.get('password'));if(access.teacher||new URLSearchParams(location.search).get('next')==='backstage'){location.replace('/backstage');return;}if(!access.admin)throw Error('Only school administrators can access CRM records.');data=await rpc('load');authorised=true;$('#auth').hidden=true;$('#workspace').hidden=false;$('#staff-nav').hidden=false;$('#signout').hidden=false;$('#refresh').hidden=false;event.target.reset();message('Signed in.');if(location.hash==='#discounts')await loadDiscounts();else render();}catch(error){message(error.message,true);}finally{b.disabled=false;}};
$('#signout').onclick=async()=>{try{await logout();}finally{location.reload();}};$('#refresh').onclick=()=>reload().catch(e=>message(e.message,true));$('#close-detail').onclick=()=>$('#detail').close();window.addEventListener('hashchange',()=>{if(location.hash==='#discounts')loadDiscounts();else render();});
document.addEventListener('click',async event=>{const b=event.target.closest('[data-action]');if(!b||!authorised)return;const id=b.dataset.id;switch(b.dataset.action){case'discount-add':discountDialog();break;case'discount-edit':discountDialog(id);break;case'discount-code':{const input=$('#detail [name=code]');input.value=generateDiscountCode();break;}case'discount-copy':{try{await navigator.clipboard.writeText(discounts.find(d=>d.id===id).code);message('Discount code copied.');}catch{message('Select and copy the code from its card.');}break;}case'discount-toggle':{const item=discounts.find(d=>d.id===id);await mutate('discount_toggle',{id,enabled:!item.enabled});break;}case'analytics-range':{const end=today();analyticsRange={from:id==='year'?end.slice(0,4)+'-01-01':shiftDay(end,-Number(id)+1),to:end};location.hash='analytics';render();break;}case'metric':filter=id==='new'?{status:'New'}:id==='trials'?{trials:true}:id.startsWith('trials-')?{trials:true,trialType:id.slice(7)}:{follow:'overdue'};location.hash='leads';render();break;case'clear':filter={};render();break;case'schedule-clear':filter.classDate='';render();break;case'lead':leadDialog(id);break;case'class':classDialog(id);break;case'roster':roster(id);break;case'book':bookDialog(id);break;case'student-book':bookDialog('',id);break;case'student':studentDialog(id);break;case'membership':membershipDialog(id);break;case'convert':{const result=await mutate('convert',{lead_id:id,group_name:data.classes.find(c=>data.bookings.some(b=>b.lead_id===id&&b.class_id===c.id&&b.status==='Booked'))?.group_name||''});if(result)studentDialog(result.id);break;}case'cancel':if(confirm('Cancel this booking and release its place?')){const booking=data.bookings.find(x=>x.id===id);if(await mutate('cancel',{booking_id:id}))roster(booking.class_id);}break;}});
document.addEventListener('change',async event=>{if(event.target.matches('#schedule-filter input[name=date]')){filter.classDate=event.target.value;renderSchedule();return;}if(event.target.id==='discount-status'){discountStatus=event.target.value;renderDiscounts();return;}if(!event.target.matches('[data-attendance]'))return;const id=event.target.dataset.attendance,b=data.bookings.find(b=>b.id===id);if(await mutate('attendance',{booking_id:id,attendance:event.target.value}))roster(b.class_id);else event.target.value=b.attendance;});
document.addEventListener('submit',async event=>{const form=event.target;if(form.id==='analytics-filter'){event.preventDefault();const range=Object.fromEntries(new FormData(form));try{buildAnalytics(data,range);analyticsRange=range;render();message('Analytics updated.');}catch(error){message(error.message,true);}return;}if(form.id==='lead-filters'){event.preventDefault();filter={...Object.fromEntries(new FormData(form)),trials:filter.trials,trialType:filter.trialType};render();return;}if(form.id==='schedule-filter'){event.preventDefault();filter.classDate=new FormData(form).get('date');render();return;}if(form.id==='student-filter'){event.preventDefault();filter.studentSearch=new FormData(form).get('search');render();return;}if(!form.dataset.form)return;event.preventDefault();const d=Object.fromEntries(new FormData(form));let action=form.dataset.form;try{if(action==='discount_save'){d.enabled=form.elements.enabled.checked;const value=Number(d.value);if(!Number.isFinite(value)||value<=0||d.kind==='percent'&&value>100)throw Error('Enter a positive amount; percentages cannot exceed 100.');if(d.ends_on&&d.ends_on<d.starts_on)throw Error('The last valid day must be on or after the start date.');d.code=d.code.trim().toUpperCase();}if(action==='class'){d.starts_at=warsawToIso(d.starts_at);d.ends_at=warsawToIso(d.ends_at);if(!d.starts_at||!d.ends_at)throw Error('Choose a valid Warsaw date and time.');action='class_save';}if(action==='lead'){if(!d.email&&!d.phone)throw Error('Enter an email or phone number.');action='lead_save';}const result=await mutate(action,d);if(!result)return;if(action==='lead_save')leadDialog(result.id);else if(action==='membership')studentDialog(d.student_id);else if(action==='book')roster(d.class_id);else $('#detail').close();}catch(error){message(error.message,true);}});

// Restore only a server-validated HttpOnly session; credentials never enter browser storage.
rpc('session').then(async access=>{if(access.teacher||new URLSearchParams(location.search).get('next')==='backstage'){location.replace('/backstage');return;}if(!access.admin)return;data=await rpc('load');authorised=true;$('#auth').hidden=true;$('#workspace').hidden=false;$('#staff-nav').hidden=false;$('#signout').hidden=false;$('#refresh').hidden=false;message('Signed in.');render();}).catch(()=>{});

function renderAnalytics(){
 analyticsRange||={from:shiftDay(today(),-29),to:today()};const a=buildAnalytics(data,analyticsRange),percent=n=>n===null?'—':n+'%';
 const max=Math.max(1,...a.trend.flatMap(row=>[row.leads,row.trials])),width=600,height=140,step=width/a.trend.length;
 const chart=a.trend.map((row,i)=>`<g><title>${esc(row.date)}: ${row.leads} inquiries, ${row.trials} trial bookings</title><rect class="chart-new" x="${i*step+step*.12}" y="${height-row.leads/max*120}" width="${step*.34}" height="${row.leads/max*120}" rx="2"/><rect class="chart-trial" x="${i*step+step*.52}" y="${height-row.trials/max*120}" width="${step*.34}" height="${row.trials/max*120}" rx="2"/></g>`).join('');
 const metric=(title,value,description)=>`<article class="card analytics-metric"><small>${title}</small><strong>${value}</strong><p>${description}</p></article>`;
 $('#workspace').innerHTML=`<form id="analytics-filter" class="toolbar">${field('from','From',a.from,'date','required')}${field('to','To',a.to,'date','required')}<button class="primary">Apply dates</button></form><div class="actions analytics-presets">${[['7','7 days'],['30','30 days'],['90','90 days'],['year','This year']].map(([id,label])=>button(label,'analytics-range',id)).join('')}</div><p class="count">${esc(a.from)} → ${esc(a.to)} · inclusive dates, Warsaw time</p>
 <div class="stats analytics-stats">${metric('New inquiries',a.leadCount,'Leads created in the selected period.')}${metric('Lead conversion',percent(a.conversion),`${a.converted} of ${a.leadCount} period leads converted, as of today.`)}${metric('Trial bookings',a.trialCount,'Active trial bookings in classes scheduled during the period.')}${metric('Attendance rate',percent(a.attendance),`${a.present} present out of ${a.present+a.absent+a.noShows} recorded outcomes in completed classes.`)}${metric('Class occupancy',percent(a.occupancy),`${a.booked} active bookings / ${a.capacity} available spots across ${a.classCount} classes.`)}${metric('Memberships recorded',a.memberships,`${a.newStudents} new students created during the period.`)}</div>
 <div class="analytics-panels"><section class="card"><h2>Inquiries & trial bookings</h2><p class="count">${a.monthly?'Monthly':'Daily'} counts · inquiries use submission dates; trials use class dates.</p><div class="chart-legend"><span><i class="legend-new"></i>New inquiries</span><span><i class="legend-trial"></i>Trial bookings</span></div><svg class="analytics-trend" viewBox="0 0 600 145" role="img" aria-label="${esc(a.monthly?'Monthly':'Daily')} inquiries and trial bookings"><title>Inquiries and trial bookings from ${esc(a.from)} to ${esc(a.to)}</title><line x1="0" x2="600" y1="140" y2="140" stroke="#dfc6bf"/>${chart}</svg><div class="chart-axis"><span>${esc(a.trend[0]?.date||a.from)}</span><span>${esc(a.trend.at(-1)?.date||a.to)}</span></div><details class="analytics-data"><summary>View chart data</summary><div class="table-scroll"><table><thead><tr><th>Date</th><th>Inquiries</th><th>Trials</th></tr></thead><tbody>${a.trend.map(row=>`<tr><td>${esc(row.date)}</td><td>${row.leads}</td><td>${row.trials}</td></tr>`).join('')}</tbody></table></div></details></section>
 <section class="card"><h2>Lead milestones</h2><p class="count">For leads created in the selected period; stages reached as of today. Stages may be skipped.</p><div class="analytics-bars">${a.funnel.map(([label,value])=>`<div><div class="bar-label"><span>${label}</span><strong>${value}</strong></div><div class="bar-track"><span style="width:${a.leadCount?value/a.leadCount*100:0}%"></span></div></div>`).join('')}</div></section></div>
 <section class="card section-title"><h2>Trials & occupancy by class</h2><div class="table-scroll"><table><thead><tr><th>Class type</th><th>Classes</th><th>Trial bookings</th><th>Booked / capacity</th><th>Occupancy</th></tr></thead><tbody>${a.groups.map(g=>`<tr><td>${g.label}</td><td>${g.classes}</td><td>${g.trials}</td><td>${g.booked} / ${g.capacity}</td><td>${percent(g.occupancy)}</td></tr>`).join('')}</tbody></table></div></section>
 <div class="analytics-panels section-title"><section class="card"><h2>Lead sources</h2><div class="table-scroll"><table><thead><tr><th>Source</th><th>Leads</th><th>Converted</th><th>Conversion</th></tr></thead><tbody>${a.sources.map(source=>`<tr><td>${esc(source.source)}</td><td>${source.leads}</td><td>${source.converted}</td><td>${percent(source.rate)}</td></tr>`).join('')||'<tr><td colspan="4">No inquiries in this period.</td></tr>'}</tbody></table></div></section>
 <section class="card"><h2>Attendance details</h2><dl class="analytics-facts"><dt>Present</dt><dd>${a.present}</dd><dt>Absent</dt><dd>${a.absent}</dd><dt>No-shows</dt><dd>${a.noShows} · ${percent(a.noShowRate)}</dd><dt>Completed bookings awaiting attendance</dt><dd>${a.pending}</dd><dt>Cancelled bookings in period classes</dt><dd>${a.cancelled}</dd></dl><p class="count">Attendance percentages exclude upcoming classes and unrecorded outcomes. Cancelled bookings are excluded.</p></section></div>
 <section class="card section-title"><h2>Current school health</h2><p class="count">As of ${esc(a.currentDay)} · these figures are not limited by the date filter.</p><div class="analytics-health"><div><strong>${a.activeMembers}</strong><span>Students with an active membership and sessions remaining</span></div><div><strong>${a.expiring}</strong><span>Active memberships expiring in the next 30 days</span></div><div><strong>${a.overdue}</strong><span>Overdue follow-ups</span></div></div></section>
 <p class="notice">Based only on CRM records. No tracking pixels or visitor analytics are added. Membership purchases are manually recorded entries; payment totals and revenue are not tracked here.</p>`;
}

const discountAudiences=[['all','All group classes'],['solo','Solo partner groups'],['couples','Couple groups'],['ladies','Ladies’ Solo']];
function discountState(d){return !d.enabled?'Disabled':d.ends_on&&d.ends_on<today()?'Expired':d.starts_on>today()?'Scheduled':'Active';}
function generateDiscountCode(){const bytes=crypto.getRandomValues(new Uint8Array(8));return 'AURA-'+Array.from(bytes,b=>'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'[b%32]).join('');}
async function loadDiscounts(){try{discounts=await rpc('discount_list');if(location.hash==='#discounts')render();}catch(error){message(error.message,true);}}
function renderDiscounts(){const rows=discounts.filter(d=>discountStatus==='all'||discountState(d)===discountStatus);$('#workspace').innerHTML=`<div class="toolbar"><label>Status<select id="discount-status">${['all','Active','Scheduled','Expired','Disabled'].map(v=>'<option value="'+v+'" '+(v===discountStatus?'selected':'')+'>'+(v==='all'?'All discounts':v)+'</option>').join('')}</select></label>${button('Create discount','discount-add','','class="primary"')}</div><p class="notice">Reusable discount codes for 1-, 3- and 6-month class packages. The last valid day is inclusive, in Warsaw time. Codes work in the website’s package payment preview; no payment is collected.</p><p class="count">${rows.length} discount${rows.length===1?'':'s'}</p><div class="list">${rows.map(d=>`<article class="card row"><div><strong class="discount-code">${esc(d.code)}</strong> <span class="pill">${discountState(d)}</span><p>${esc(d.label)}${d.label?' · ':''}${d.value}${d.kind==='percent'?'%':' zł'} off · ${esc(discountAudiences.find(([id])=>id===d.class_type)?.[1])} · ${d.months?d.months+' months':'All packages'}</p><small>${esc(d.starts_on)} → ${esc(d.ends_on||'No end date')}</small></div><div class="actions">${button('Copy code','discount-copy',d.id)}${button('Edit','discount-edit',d.id)}${button(d.enabled?'Disable':'Enable','discount-toggle',d.id)}</div></article>`).join('')||'<div class="card empty">'+(discounts.length?'No discounts match this status.':'No discounts here yet. Create a code to get started.')+'</div>'}</div>`;}
function discountDialog(id){const d=discounts.find(x=>x.id===id)||{};modal(id?'Edit discount':'Create class discount',`<form data-form="discount_save"><input type="hidden" name="id" value="${esc(d.id||'')}"><div class="discount-code-row">${field('code','Discount code',d.code||generateDiscountCode(),'text','required minlength="4" maxlength="40" pattern="[A-Za-z0-9][A-Za-z0-9_-]{3,39}"')}${button('Generate code','discount-code')}</div>${field('label','Internal label (optional)',d.label||'','text','maxlength="120"')}<div class="two">${select('kind','Discount type',[['percent','Percentage (%)'],['fixed','Amount (zł)']],d.kind||'percent')}${field('value','Discount value',d.value||10,'number','required min="0.01" max="100000" step="0.01"')}${select('class_type','Eligible classes',discountAudiences,d.class_type||'all')}${select('months','Package duration',[['','All durations'],['1','1 month'],['3','3 months'],['6','6 months']],d.months?String(d.months):'')}${field('starts_on','First valid day',d.starts_on||today(),'date','required')}${field('ends_on','Last valid day (optional)',d.ends_on||'','date')}</div><label class="discount-enabled"><input type="checkbox" name="enabled" ${d.enabled===false?'':'checked'}>Active code</label><p class="count">One code per package; discounts do not stack. A fixed discount cannot reduce the price below zero. Codes can be reused until disabled or expired.</p><button class="primary">Save discount</button></form>`);}
